python3 -c "
import json
with open('/app/resources/treasury_bulletin_2007_12.json', 'r') as f:
    data = json.load(f)

# Look for sections with TIPS data
for key in data.keys():
    if 'tips' in key.lower() or 'pd2' in key.lower() or 'pdo' in key.lower():
        print(f'Key: {key}')
        if isinstance(data[key], list):
            print(f'  Length: {len(data[key])}')
            if len(data[key]) > 0:
                print(f'  First item: {data[key][0]}')
        elif isinstance(data[key], dict):
            print(f'  Keys: {list(data[key].keys())[:10]}')
        print()
"
